args<-commandArgs(FALSE);script<-sub('^--file=','',args[grepl('^--file=',args)][1])
setwd(normalizePath(file.path(dirname(script),'..'),mustWork=TRUE))
source('R/model.R');x<-load_inputs();cal<-calibrate(x);a<-default_assumptions()
b<-project_model(x,a,cal);m<-b$path
checks<-data.frame(check=character(),passed=logical())
check<-function(label,z){checks[nrow(checks)+1,]<<-list(label,isTRUE(z));if(!isTRUE(z))stop('Failed: ',label)}
near<-function(x,y,tol=1e-6)all(is.finite(c(x,y)))&&max(abs(x-y))<tol
check('No duplicate population age-sex-year cells',!anyDuplicated(x$population[,c('year','age','sex')]))
check('Single-year population covers every age 0-100 and both sexes',all(table(x$population$year)==202))
check('IGR population total reconciliation',near(as.numeric(tapply(x$population$population,x$population$year,sum)),x$labour$population))
check('Observed labour profiles are populated',nrow(x$rates)==22&&nrow(x$hours)==22&&all(x$hours$hours_per_worker>0))
check('Projected participation remains in bounds',all(x$labour$participation>0 & x$labour$participation<1))
check('Average hours follow published IGR trend',near(tail(x$labour$average_hours,1)/x$labour$average_hours[x$labour$year==2026],.999^40))
check('Hours employment identity',near(x$labour$total_hours,x$labour$employed*x$labour$average_hours*52))
check('Age Pension eligibility uses age 67',near(b$pension$eligible_population[1],sum(subset(x$population,year==2030&age>=67)$population)))
check('Eight spending modules include distinct NDIS and aged care',length(unique(b$components$programme))==8&&all(c('NDIS','Aged care')%in%b$components$programme))
gfs<-subset(x$operating,year==2025)
check('No double counting of care pension or conventional interest',near(sum(cal$programmes$base_2025_bn),
  (gfs$value[gfs$item=='Total GFS expenses']-gfs$value[gfs$item=='Interest expenses n.e.c.'])/1000,.002))
check('Observed NDIS allocation matches audited plan expenses',near(cal$programmes$base_2025_bn[cal$programmes$programme=='NDIS'],46.352178))
check('Older NDIS recipients are retained',all(x$ndis$participants_65plus>0))
check('NDIS incidence below 65 and cohort recursion remain finite',all(is.finite(x$ndis$participants))&&all(x$ndis$participants>0))
check('PBO spending dollars match exactly at anchor',near(m$total_spending_bn[1],cal$official$expenses_billion_dollars+cal$official$net_capital_investment_billion_dollars))
check('PBO revenue dollars match exactly at anchor',near(m$revenue_bn[1],cal$official$revenue_billion_dollars))
check('PBO gross and net debt anchors match',near(m$gross_debt_bn[1],cal$official$gross_debt_billion_dollars)&&near(m$net_debt_bn[1],cal$official$net_debt_billion_dollars))
check('Programme calibration factor common to all modules',length(unique(cal$programmes$calibration_factor))==1)
check('Programmes sum to primary expenses',near(as.numeric(tapply(b$components$spending_bn,b$components$year,sum)),m$primary_expense_bn))
check('Revenue heads sum to total revenue',near(rowSums(b$revenue[,-1]),m$revenue_bn))
check('ABS tax-head totals match national consolidated GFS',near(sum(subset(x$tax_history,year==2025)[,-1]),gfs$value[gfs$item=='Taxation revenue']/1000))
check('Personal and Medicare taxes are separate heads',all(c('personal_income','medicare_fbt')%in%names(b$revenue)))
check('ATO uses 100 actual percentile cells',nrow(x$income_distribution)==100&&all(x$income_distribution$count>0))
check('Tax is zero below tax-free threshold',income_tax(18000)==0)
check('2027-28 lower tax rate is legislated 14 percent',near(income_tax(190000,year=2030),51102))
check('LITO applied at 45000',near(income_tax(45000),3427))
check('Schedule indexation scales tax proportionately',near(income_tax(c(40000,85000,200000)*1.5,1.5),income_tax(c(40000,85000,200000))*1.5))
wage<-project_model(x,modifyList(a,list(tax_policy='wage_indexed')),cal)
check('Wage indexation is the default threshold convention',identical(a$tax_policy,'wage_indexed'))
check('Wage-indexed default removes real bracket creep',near(b$revenue_diagnostics$bracket_creep_revenue_bn,rep(0,nrow(m))))
check('Wage-indexed bracket creep counterfactual is zero',near(wage$revenue_diagnostics$bracket_creep_revenue_bn,rep(0,nrow(m))))
fixed<-project_model(x,modifyList(a,list(tax_policy='fixed')),cal)
cpi<-project_model(x,modifyList(a,list(tax_policy='cpi')),cal)
check('Fixed thresholds generate more PIT than CPI indexation',tail(fixed$revenue$personal_income,1)>tail(cpi$revenue$personal_income,1))
check('CPI thresholds generate more PIT than wage indexation',tail(cpi$revenue$personal_income,1)>tail(wage$revenue$personal_income,1))
check('Changing threshold rule does not recalibrate 2030 revenue',near(fixed$path$revenue_bn[1],m$revenue_bn[1]))
check('Fixed-threshold reported bracket creep reconciles',near(fixed$revenue_diagnostics$bracket_creep_revenue_bn,
  fixed$revenue$personal_income-wage$revenue$personal_income))
check('Low wealth single receives full annual pension',near(pension_entitlement(x,0,0),1237.7*26))
check('Low wealth couple receives correct per-person pension',near(pension_entitlement(x,0,0,couple=TRUE),933*26))
check('Assets test tapers and cuts off benefit',pension_entitlement(x,700000,0)<pension_entitlement(x,100000,0)&&pension_entitlement(x,2000000,0)==0)
check('Income test reduces benefit',pension_entitlement(x,0,0,other_income_annual=40000)<pension_entitlement(x,0,0))
check('Non-homeowner asset threshold is higher',pension_entitlement(x,700000,0,homeowner=FALSE)>pension_entitlement(x,700000,0,homeowner=TRUE))
check('Pension coverage bounded',all(b$pension$coverage>=0 & b$pension$coverage<=1))
std<-project_model(x,modifyList(a,list(policy='standards')),cal)
check('Relative standards preserve eligibility coverage',near(std$pension$coverage,rep(std$pension$coverage[1],37)))
check('No automatic tax closure or spending recalibration',near(std$path$primary_expense_bn[1],m$primary_expense_bn[1]))
low_return<-project_model(x,modifyList(a,list(super_real_return=.02)),cal)
high_return<-project_model(x,modifyList(a,list(super_real_return=.07)),cal)
pension_end<-function(z)tail(subset(z$components,programme=='Age Pension')$share_gdp,1)
check('Higher private returns reduce pension spending',pension_end(low_return)>pension_end(b)&&pension_end(b)>pension_end(high_return))
check('Higher private returns reduce debt',tail(low_return$path$net_debt_pct,1)>tail(m$net_debt_pct,1)&&tail(m$net_debt_pct,1)>tail(high_return$path$net_debt_pct,1))
check('Private returns leave GDP unchanged',near(low_return$path$nominal_gdp,high_return$path$nominal_gdp))
check('Private returns leave superannuation taxes unchanged',near(low_return$revenue$superannuation,high_return$revenue$superannuation))
check('Private returns leave public asset yield unchanged',near(low_return$path$interest_receipts_bn[-1]/head(low_return$path$financial_assets_bn,-1),
  high_return$path$interest_receipts_bn[-1]/head(high_return$path$financial_assets_bn,-1)))
check('Private returns leave anchor pension spending unchanged',near(low_return$path$primary_expense_bn[1],high_return$path$primary_expense_bn[1]))
std_high<-project_model(x,modifyList(a,list(policy='standards',super_real_return=.07)),cal)
check('Private return control inactive under relative standards',near(std_high$path$net_debt_pct,std$path$net_debt_pct))
hi<-project_model(x,modifyList(a,list(productivity=.022)),cal)
check('Productivity real-output multiplier is exact',near(tail(hi$path$real_output_index/m$real_output_index,1),(1.022/1.012)^36))
check('Productivity leaves nominal GDP unchanged',identical(hi$path$nominal_gdp,m$nominal_gdp))
ng<-project_model(x,modifyList(a,list(ngdp_per_capita_growth=.04)),cal)
check('NGDP equals compounded per capita and population growth',near(ng$path$nominal_gdp_growth[-1],rep(1.04*(1+a$population_growth)-1,36)))
check('Nominal real and price identity',near(ng$path$nominal_gdp/cal$gdp0,ng$path$real_output_index*ng$path$domestic_price_index*ng$path$income_effect))
tt<-project_model(x,modifyList(a,list(tot_change=.2)),cal)
check('Terms of trade does not change real production',near(tt$path$real_output_index,m$real_output_index))
check('Terms of trade increases royalty receipts',tail(tt$revenue$royalties,1)>tail(b$revenue$royalties,1))
rp<-project_model(x,modifyList(a,list(relative_price=.013)),cal)
check('Service prices do not directly index cash pensions',near(subset(rp$components,programme=='Age Pension')$spending_bn,subset(b$components,programme=='Age Pension')$spending_bn))
check('Negative productivity has no hidden floor',tail(macro_path(x,modifyList(a,list(productivity=-.005)))$productivity_index,1)<1)
stress<-list(a,modifyList(a,list(productivity=.03,relative_price=-.005,interest_rate=.02)),
  modifyList(a,list(productivity=-.005,relative_price=.02,interest_rate=.07)),modifyList(a,list(tax_policy='fixed')))
for(i in seq_along(stress)) {
  v<-project_model(x,stress[[i]],cal)$path
  check(paste('Net debt stock-flow identity',i),near(diff(v$net_debt_bn),-v$fiscal_balance_bn[-1],1e-5))
  check(paste('Gross debt financing identity',i),near(diff(v$gross_debt_bn),-v$fiscal_balance_bn[-1]+v$net_financial_asset_acquisition_bn[-1],1e-5))
  check(paste('Interest charged on opening gross debt',i),near(v$interest_bn[-1],head(v$gross_debt_bn,-1)*v$effective_interest_rate[-1]))
  check(paste('Receipts earned on opening assets',i),near(v$interest_receipts_bn[-1],head(v$financial_assets_bn,-1)*cal$asset_yield))
  check(paste('Gross minus assets equals net debt',i),near(v$gross_debt_bn-v$financial_assets_bn,v$net_debt_bn))
  check(paste('All fiscal outputs finite',i),all(is.finite(v$total_spending_bn))&&all(is.finite(v$net_debt_bn)))
}
all_controls<-modifyList(a,list(productivity=.02,ngdp_per_capita_growth=.05,relative_price=.01,tot_change=.2))
attr<-scenario_attribution(x,all_controls,cal)
check('Shapley allocation reconciles all four controls and interactions',near(sum(attr$net_debt_change_pp),
  tail(project_model(x,all_controls,cal)$path$net_debt_pct-m$net_debt_pct,1)))
drivers<-spending_driver_audit(b)
mechanical<-subset(drivers,programme!='Defence')
check('Number cost intensity identity reproduces every non-target spending level',near(mechanical$implied_spending_bn,mechanical$spending_bn,1e-5))
check('Real driver identity reproduces every non-target GDP share',near(mechanical$implied_share_gdp,mechanical$share_gdp))
check('Defence target is explicitly excluded from driver identity',all(is.na(subset(drivers,programme=='Defence')$implied_share_gdp)))
end_share<-function(p,y)subset(b$components,programme==p & year==y)$share_gdp
check('Ageing and costs increase health and aged care GDP shares',
  end_share('Health',2066)>end_share('Health',2030)&&end_share('Aged care',2066)>end_share('Aged care',2030))
check('Health and care age-weighted demand grow faster than total population',
  all(subset(drivers,year==2066 & programme%in%c('Health','Aged care'))$exposure_index>tail(m$population_index,1)))
check('Pure nominal GDP override leaves programme GDP shares unchanged',near(ng$components$share_gdp,b$components$share_gdp))
service<-b$components$programme%in%c('Aged care','NDIS','Other social protection','Other public services')
check('Extra service prices compound into service GDP shares',near(rp$components$share_gdp[service]/b$components$share_gdp[service],
  ((1+rp$assumptions$relative_price)/(1+a$relative_price))^(b$components$year[service]-2030)))
detail<-b$subfunctions;loading<-x$health_education_parameters$relative_price_loading[match(detail$id,x$health_education_parameters$id)]
keep<-!is.na(loading)
check('Health/education relative prices respect medicine and funding exclusions',near(rp$subfunctions$spending_bn[keep]/detail$spending_bn[keep],
  ((1+rp$assumptions$relative_price)/(1+a$relative_price))^((detail$year[keep]-2030)*loading[keep])))
dir.create('outputs',showWarnings=FALSE)
write.csv(drivers,'outputs/spending_driver_audit.csv',row.names=FALSE)
write.csv(checks,'outputs/validation_checks.csv',row.names=FALSE)
write.csv(m,'outputs/reference_projection.csv',row.names=FALSE)
write.csv(b$components,'outputs/reference_components.csv',row.names=FALSE)
write.csv(b$revenue,'outputs/reference_revenue.csv',row.names=FALSE)
write.csv(b$revenue_diagnostics,'outputs/reference_revenue_diagnostics.csv',row.names=FALSE)
write.csv(cal$programmes,'outputs/programme_calibration.csv',row.names=FALSE)
scenario_inputs<-economic_inputs(x,a)
write.csv(scenario_inputs$labour,'outputs/labour_projection.csv',row.names=FALSE)
write.csv(scenario_inputs$ndis,'outputs/ndis_participant_projection.csv',row.names=FALSE)
write.csv(b$pension,'outputs/pension_projection.csv',row.names=FALSE)
capture.output(sessionInfo(),file='outputs/session_info.txt')
cat(nrow(checks),'updated model checks passed.\n')
